import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"KV Cache Quantization for Self-Forcing Video Generation: A 33-Method Empirical Study","description":"","frontmatter":{"title":"KV Cache Quantization for Self-Forcing Video Generation: A 33-Method Empirical Study","arxiv":"2603.27469","date":"2026-03-29","authors":"Suraj Ranganath, Vaishak Menon, Anish Patnaik","categories":"cs.LG, cs.AI","topics":"KV cache 压缩, 量化, 自回归视频生成","outline":[2,2]},"headers":[],"relativePath":"papers/2603.27469.md","filePath":"papers/2603.27469.md","lastUpdated":null}'),p={name:"papers/2603.27469.md"};function l(r,s,i,c,m,o){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="kv-cache-quantization-for-self-forcing-video-generation-a-33-method-empirical-study" tabindex="-1">KV Cache Quantization for Self-Forcing Video Generation: A 33-Method Empirical Study <a class="header-anchor" href="#kv-cache-quantization-for-self-forcing-video-generation-a-33-method-empirical-study" aria-label="Permalink to &quot;KV Cache Quantization for Self-Forcing Video Generation: A 33-Method Empirical Study&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2603.27469" target="_blank" rel="noreferrer">2603.27469</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-03-29</td></tr><tr><td><strong>作者</strong></td><td>Suraj Ranganath, Vaishak Menon, Anish Patnaik</td></tr><tr><td><strong>分类</strong></td><td>cs.LG, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>在同一套 Self-Forcing/Wan2.1 端到端 harness 上横评 33 种 KV cache 压缩方案，用「峰值显存 / 运行时 / 实际压缩比 / VBench 真实感 / 对 BF16 的结构保真 / 终端漂移」六轴联评，指出名义压缩比与实际显存节省经常脱节。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/acceleration-distillation">加速与蒸馏</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">论文性质</p><p>这是一篇<strong>纯实证研究</strong>，不提出新方法，产出物是一套 benchmark harness、分析流程与配套 Streamlit 看板。作者为加州大学圣地亚哥分校三人组。代码与数据见 github.com/suraj-ranganath/kv-quant-longhorizon。文中 FlowCache 相关行是作者的<strong>自研改编</strong>，非上游官方实现在 Wan2.1 上的复现。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>Self-Forcing 类自回归视频生成靠「把已生成内容反复喂回去当上下文」把短时程模型推到长 rollout。这条扩展路径立刻撞上一个系统瓶颈：KV cache 随 rollout 长度增长，必须被存储、读取、写入，某些方案还要反复变换。于是「能生成多长」不只由模型质量决定，也由显存容量、带宽以及缓存状态的实现方式决定。</p><p>论文提出的具体问题很实际：<strong>如果压缩 KV cache，哪些方法真的改善端到端长视频生成，哪些只是在纸面上看起来高效？</strong> 一个方法完全可以报出漂亮的名义压缩比，却因为引入巨大的反量化缓冲、刷新开销或 rollout 下的质量坍塌而在部署中失败。这个问题之所以值得单独立项，是因为在视频生成里系统轴与质量轴<strong>无法干净分离</strong>：可用的方法必须同时做到显存降得够多、算得动、看起来真实、并且不相对无压缩参考发生结构漂移。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>三条线在这里交汇。视频基座侧，Movie Gen 与 Wan 证明规模、上下文长度与推理工程能撑起高质量生成；Self-Forcing 把 KV 缓存 rollout 从下游系统优化变成了训练与推理的一部分。系统侧，PagedAttention 在语言模型上把「KV 内存管理是一等瓶颈」这件事讲透了，FlowCache 把它推广到自回归视频生成的分块缓存策略。量化侧，KIVI 用键通道非对称、值 token 非对称的统计感知量化做低比特 cache，QuaRot 用 Hadamard 旋转把激活转到更适合低比特的基上以压制离群值，Quant VideoGen（QVG）则给自回归视频生成提出免训练的 KV 量化框架。</p><p>这些工作各自都有说服力，但论文指出的空缺很直白：<strong>它们没有在同一套端到端视频生成 harness 上被一起测过</strong>。每篇论文的硬件、骨干、评测协议、甚至「压缩比」的定义都不同，因此无法回答「在同一个 Self-Forcing/Wan2.1 栈上该选谁」。更麻烦的是，几乎没人同时报告名义压缩比与<strong>实测峰值显存</strong>——而后者才是单卡能否跑起来的判据。论文还诚实地记录了一个现实约束：FlowCache 的官方实现不支持这里用的 Self-Forcing Wan2.1 栈，QVG 在 2026-03-17 时点未找到与 arXiv 记录关联的官方代码，所以对应行只能是自研改编或暂缺。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用这篇论文之前的公开知识，思路是这样的。第一，自回归视频 rollout 的 cache 增长与时间成正比，这是纯粹的定义性事实；语言模型侧已经证明 KV 管理能成为吞吐上限。第二，低比特量化在 LLM 上已有一整套成熟工具（RTN、KIVI、QuaRot），把它们端到视频 DiT 上是第一步。第三，也是最容易被忽视的一步：任何工程师做过一次量化落地都知道，<strong>「压缩了张量」与「降低了峰值显存」是两件事</strong>——只要 attention 读取路径还要把低比特张量重建成 BF16，峰值就由那个瞬时缓冲决定，而不是由稳态存储决定。这个直觉不需要新实验就能得到，但要证明它必须做端到端 profiling，而恰恰没人做。</p><p>于是研究设计几乎是被逼出来的：把所有能想到的设计族（朴素量化、非对称量化、旋转量化、渐进残差编码、时间启发式、空间混合精度、缓存保留/剪枝策略）统一实现在一个 harness 里，在生成入口挂一个可选量化器，同时记录运行时与峰值显存，再单独跑 VBench 与对 BF16 的逐帧保真。空间混合精度这一族的加入则来自一个视觉直觉：前景重要、背景不重要，值得一试（结果它成了全文最有价值的负结果）。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>对长时程视频生成来说，「压缩比」是一个几乎没有决策价值的数字。真正决定能不能部署的是<strong>峰值显存</strong>，而峰值由实现中最大的那个瞬时 BF16 缓冲决定，与稳态压缩率可以完全解耦。与此并列的第二个洞察是：<strong>「看起来是段好视频」与「还是原来那段视频」是两个正交的轴</strong>。压缩后的模型可以在无参考真实感指标上与 BF16 打平，同时在对 BF16 的 SSIM 上只剩 0.54 —— 它生成了另一段同样合理的视频。任何只报一个数的评测都会在这两点上骗人。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>不是方法论文，pipeline 指的是评测流程。设定：Wan2.1 版 Self-Forcing 栈，每次 rollout 生成 165 帧、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">480</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">832</span></span></span></span>、16 fps，约 10.3 秒。</p><ol><li><strong>方法接入</strong>。统一生成入口在因果 KV cache 边界处挂一个可选量化器，记录运行时与峰值显存，写出逐 prompt 视频与 trace。33 个变体分七族：BF16 参考；RTN（INT2/INT4/K2V4/近期窗保护/周期刷新）；KIVI（对应变体）；QuaRot（旋转后再做 RTN 式编码，同样带近期窗与刷新变体）；本项目自研的高保真量化器（PRQ 两阶段渐进残差编码、QAQ 离群值单独存储）；时间启发式（Age-Tier 近新高精度、旧的更狠压；TPTQ 加 PRQ 编码旧区 + 显式离群保留）；FlowCache 改编族（Hybrid 按块龄与层分配预算、Adaptive 加漂移感知分配、Prune 硬淘汰低重要块、Soft-Prune 用摘要替换被淘汰块、Native 复用内部特征）；空间混合精度（运动导出的掩码，前景用高保真编码器、背景用便宜的）。</li><li><strong>两个 benchmark</strong>。MovieGen 风格单镜头 prompt 集，考察孤立 10 秒样本的系统行为与逐 prompt 质量；StoryEval 用 10 条叙事型 prompt，考察更长因果 rollout 下的稳定性，用前缀质量曲线与终端 drift-last 分数总结。</li><li><strong>六轴评测</strong>。峰值显存（生成日志里的最大分配）、运行时（逐 prompt 端到端墙钟）、压缩比（BF16 等效 KV 足迹 / 压缩后足迹）、VBench imaging quality、对 BF16 参考的逐帧对齐 SSIM/LPIPS/PSNR、以及前缀曲线末点的 drift-last。论文明说 PSNR 只作完整性报告 —— BF16 对自己是无穷，部分压缩方法若有若干帧完全一致也会得到非有限聚合值，所以决策主要看 SSIM 与 LPIPS。</li><li><strong>数据产物</strong>。610 条 prompt 级记录聚合成 63 条方法级摘要，论文全部表图与看板都从这一份数据生成。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><p>补充一点可从报告数据直接算出的关系，它正是全文最核心的发现：峰值显存近似为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">Peak</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">model+act</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mop"><span class="mop">max</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">comp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0502em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">recon</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">comp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是压缩后的稳态 KV 存储、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0502em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">recon</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是 attention 读取或刷新时materialize 出来的瞬时 BF16 缓冲。论文的 trace 给出了一组具体值：RTN_INT4_REFRESH 在某条 MovieGen prompt 上峰值 21.41 GB，而彼时活跃 KV 的 BF16 等效为 11.25 GB、压缩态仅 3.51 GB；RTN_INT4_RECENT2 对应 20.47 GB / 11.25 GB / 4.62 GB。可见 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0502em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">recon</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 项已经吃掉了全部压缩收益，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">comp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 降到多低都无关紧要。这解释了为什么压缩比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3.20</span><span class="mord">×</span></span></span></span> 的 RTN_INT4 的峰值（19.98 GB）反而略高于 BF16 的 19.28 GB。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问：朴素低比特够不够？</strong> 不够，而且失败方式很清楚。RTN_INT4 在两个 benchmark 上都取得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3.20</span><span class="mord">×</span></span></span></span> 名义压缩，峰值显存却是 19.98 GB 对 BF16 的 19.28 GB —— 基本没降，还把结构保真打到 SSIM 0.688（MovieGen）/ 0.661（StoryEval）。</p><p><strong>问：保真最好的方法就该部署吗？</strong> 不该。PRQ_INT4 在 MovieGen 上 SSIM 0.824、LPIPS 0.082，是最接近 BF16 的压缩方法之一，StoryEval 上 SSIM 0.724 且 drift-last 在非 BF16 方法里最高，但代价是约 160 s/prompt（BF16 只要 58.6 s）与 20.69 GB 峰值。QUAROT_KV_INT4 类似：质量优于朴素 RTN，但 236–240 s 运行时、峰值仍近 20 GB。</p><p><strong>问：实际最优操作点在哪？</strong> FLOWCACHE_SOFT_PRUNE_INT4。MovieGen 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5.49</span><span class="mord">×</span></span></span></span> 压缩、峰值 11.71 GB（BF16 19.28 GB）、75.0 s、imaging quality 0.739（与 BF16 的 0.739 完全相同）、drift-last 0.738；StoryEval 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5.42</span><span class="mord">×</span></span></span></span>、11.76 GB、drift-last 0.679（BF16 0.695）。这是当前栈上唯一同时做到「大压缩比 + 真实显存下降 + 可接受运行时」的区域。</p><p><strong>但这里有一个作者自己命名的悖论</strong>：这个部署赢家在对 BF16 的保真上很差 —— SSIM 只有 0.544（MovieGen）/ 0.518（StoryEval），明显劣于 PRQ 的 0.824 / 0.724。也就是说它生成的是<strong>另一段同样好看的视频</strong>，而不是原来那段。论文把这一点当作正面科学发现来讲：感知合理性与结构保真在长时程视频生成里可以剧烈分离。</p><p><strong>问：直觉靠得住吗？</strong> 空间混合精度是最干净的负结果。「前景比背景重要」是一个非常合理的视觉先验，但在自回归 rollout 下它与模型的真实因果依赖不匹配：QuaRot 前景 + RTN 背景的变体在两个 benchmark 上 imaging quality 崩到 0.399 / 0.400、drift 0.394 / 0.398，尽管它的峰值显存 14.38 GB 其实优于所有 RTN/QuaRot 变体。</p><p><strong>问：结论稳吗？</strong> 跨 benchmark 的方法级摘要相关性：压缩比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.9999</span></span></span></span>、运行时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.9996</span></span></span></span>、峰值显存 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.99999</span></span></span></span>、imaging quality <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.9318</span></span></span></span>、drift-last <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.9374</span></span></span></span>。需要注意前三个几乎是恒等式 —— 压缩比与显存是方法属性，与 prompt 内容基本无关，报得再高也不构成「结论稳健」的证据；只有 0.93 那两个是有信息量的。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：在自回归视频生成里，名义 KV 压缩比与实际峰值显存经常脱节，因为 attention 读取与刷新阶段仍会 materialize 大块 BF16 缓冲，trace 显示压缩态 3.51 GB 的配置峰值仍达 21.41 GB。当前 Wan2.1/Self-Forcing 栈上唯一真正的部署赢家是 FlowCache 式软剪枝 INT4（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5.4</span><span class="mord">×</span></span></span></span> 压缩、峰值 19.28→11.7 GB、运行时开销温和）。保真最好的方法（PRQ_INT4、QUAROT_KV_INT4）是研究赢家而非部署赢家，它们用 2.7–4 倍运行时或更高峰值换质量。感知真实感（VBench）与对 BF16 的结构保真（SSIM）会剧烈分离：部署赢家的 imaging quality 与 BF16 相同但 SSIM 只有 0.54。空间混合精度这个看似合理的视觉先验在自回归 rollout 下彻底失败，是一条有价值的负结果。</p><p><strong>三句话版</strong>：本文在统一 harness 上横评 33 种 KV cache 压缩方案，用六轴联评替代单分排行榜。核心结论是「部署赢家」与「研究赢家」不是同一批方法，且许多方法的显存收益被实现中的瞬时 BF16 重建吃光。可感知的真实感与对无压缩参考的结构保真必须分开报告。</p><p><strong>一句话版</strong>：KV 压缩比是纸面数字，峰值显存与结构保真才是决策变量，而这三者在长视频生成里可以彼此背离。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>方法排名被各方法的实现完成度所混杂，而论文自己就证明了这一点。</strong> §5.4 明确指出 QuaRot、RTN_RECENT2、RTN_REFRESH 的高峰值来自「当前集成方式」会重建或保留大块 BF16 张量，并把它们称为「transient systems effects，不是压缩在数学上失败的证据」。这句话逻辑上成立，但它同时抽掉了整个排行榜的地基：如果峰值显存主要由集成质量决定，而 FlowCache 族由作者亲自改编、其余方法是移植的第三方算法，那么「FlowCache 软剪枝是最佳操作点」这一头条结论就无法与「作者对自己实现的那一族做了更好的内存工程」区分开。</p><p>论文没有提供任何能切断这层混杂的证据：既没有报告各方法在<strong>同一段 attention 读取路径</strong>下的实现（例如统一的融合反量化 kernel），也没有给出「若把 recency 保护实现成不 materialize BF16，峰值会是多少」的下界估计。作者在 Future Work 里把这件事列为第一优先，等于承认了缺口。在这项工作完成之前，本文的结论应当被读作「在这一套具体实现下」的工程快照，而非关于算法族的一般结论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 33 种方法，一周内可做：</p><ul><li>只取三个配置：BF16、RTN_INT4、FLOWCACHE_SOFT_PRUNE_INT4，跑同一组 20 条 prompt。</li><li>为每个配置插桩两条曲线：稳态压缩 KV 字节数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">comp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span> 与该时刻的总分配显存 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Alloc</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span>，二者按同一时间轴对齐。</li><li>关键改动：给 RTN_INT4 加一个<strong>分块反量化</strong>的 attention 读取（每次只 materialize 一个 head/一个 chunk 的 BF16，而非整段 cache），其余完全不动。</li><li>判据：若 RTN_INT4 的峰值从 19.98 GB 掉到接近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">19.28</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">11.25</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3.5</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">11.5</span></span></span></span> GB 量级，则「排名被实现混杂」成立，§9 的质疑坐实，且说明大量被判为「不实用」的算法其实只是实现未优化；若峰值基本不动，则瓶颈在别处（例如激活而非 cache），本文的操作点建议可以直接采信。</li></ul><p>这个实验只需改一处读取路径，不涉及重训。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对 drift-last 这一轴，有一个几乎致命的观察：<strong>它与 imaging quality 在每一行都几乎相等。</strong> MovieGen 上 BF16 是 0.739/0.739、SoftPrune 0.739/0.738、Prune 0.727/0.726、PRQ 0.739/0.739、QuaRot 0.738/0.738、Recent2 0.736/0.735、Refresh 0.736/0.735、Spatial 0.399/0.394；StoryEval 上同样成对贴合。八行里最大差值是 0.005。换言之，「终端漂移」这一轴在 10 秒尺度上<strong>没有测到任何独立于整体画质的信息</strong>，它退化成了 imaging quality 的复读。跨 benchmark 的 drift 相关性 0.9374 与 imaging quality 的 0.9318 几乎相同，进一步印证两者同源。</p><p>这直接削弱了论文的一条方法论主张（「六轴联评比单分更有信息量」）：六轴里至少有一轴是冗余的，而另外两轴（压缩比、峰值显存）之间也高度确定。真正独立的轴其实只有三条：峰值显存、运行时、以及「真实感 vs 结构保真」这一对。</p><p>要把这条反例做实，只需一个更长的 rollout：论文自己在 Future Work 里承认 10 秒是「短时程代理」，20 秒以上才会出现更严重的一致性失败。反对者的最强版本是：<strong>在 10 秒内，所有非崩溃方法的漂移都还没开始，因此本文关于「rollout 稳定性」的全部结论都是在漂移发生之前测的</strong>；一旦推到 60 秒，方法排名很可能与现在完全不同——例如 SoftPrune 的摘要替换可能在长程上累积语义漂移，而 Recent2 的近期窗保护可能反超。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限驱动</strong>：本文最有价值的发现（名义压缩 ≠ 实际显存）本质上是在说，<strong>KV 压缩的目标函数写错了</strong>。所有被评测的方法都在优化「稳态存储字节数」，而真正的约束是「整条生成时间线上的分配峰值」。这两者的差距由 attention 读取路径的 materialization 模式决定，而那部分从来不是压缩算法的设计变量。同时，SoftPrune 的 SSIM 0.54 说明另一件事：一旦允许方法「换一段同样好看的视频」，压缩问题就不再是逼近问题，而是采样问题 —— 但现有全部评测都是逼近式的（对 BF16 算 SSIM/LPIPS）。</p><p><strong>新 framing</strong>：把 KV cache 压缩重新表述为<strong>在峰值显存硬约束下的在线状态摘要问题</strong>，而不是逐张量的比特分配问题。目标不是「重建 KV 使误差最小」，而是「在任意时刻分配量不超过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 的前提下，最大化后续生成对完整历史的条件互信息」。这样一来，反量化缓冲的大小自动进入约束、摘要与剪枝自动成为可行动作，而「生成另一段合理视频」也不再是失败而是可接受解。可借鉴的相邻工具是流式算法里的 <strong>submodular streaming / 有界内存 coreset</strong>：那边已经有在硬内存上界下做在线摘要并给出近似保证的框架，而且天然处理「摘要替换被淘汰元素」这一操作（正是 SoftPrune 在做但没有理论支撑的事）。</p><p><strong>第一个实验</strong>：在本文的 harness 上加一条「显存预算控制器」——给定硬上界 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span>（例如 12 GB），控制器在每个 chunk 边界根据当前分配动态选择动作（保留 BF16 / 量化 / 摘要 / 淘汰），而不是按固定策略。基线是本文的 SoftPrune 固定策略。评测除现有六轴外，加一条<strong>约束违反率</strong>（超过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 的时间比例）与 60 秒 rollout 的语义漂移（用 CLIP 与首段的相似度衰减）。若动态控制器在同一 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 下取得更低的 60 秒漂移，就说明 KV 压缩的正确抽象是资源调度而不是张量编码 —— 这会把整个子领域的问题定义换掉。</p>',47)])])}const d=a(p,[["render",l]]);export{g as __pageData,d as default};
